function leastStartingHealth(vault: number[][]): number {
  const m = vault.length, n = vault[0].length;
  // best[j] = most health possible in room (i, j) while alive, or -Infinity if unreachable
  const canFinish = (start: number): boolean => {
    const best = new Array(n).fill(-Infinity);
    for (let i = 0; i < m; i++) {
      for (let j = 0; j < n; j++) {
        let before: number;
        if (i === 0 && j === 0) before = start;
        else before = Math.max(best[j], j > 0 ? best[j - 1] : -Infinity);
        const after = before + vault[i][j];
        best[j] = after >= 1 ? after : -Infinity;
      }
    }
    return best[n - 1] >= 1;
  };
  let lo = 1, hi = 1 + (m + n - 1) * 1000;
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (canFinish(mid)) hi = mid;
    else lo = mid + 1;
  }
  return lo;
}

