class Solution:
    def leastStartingHealth(self, vault: List[List[int]]) -> int:
        m, n = len(vault), len(vault[0])
        NEG = float("-inf")

        def can_finish(start):
            best = [NEG] * n
            for i in range(m):
                for j in range(n):
                    if i == 0 and j == 0:
                        before = start
                    else:
                        before = max(best[j], best[j - 1] if j > 0 else NEG)
                    after = before + vault[i][j]
                    best[j] = after if after >= 1 else NEG
            return best[n - 1] >= 1

        lo, hi = 1, 1 + (m + n - 1) * 1000
        while lo < hi:
            mid = (lo + hi) // 2
            if can_finish(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

