function leastStartingHealth(vault: number[][]): number {
  const m = vault.length, n = vault[0].length;
  // need[j] holds the row below while we fill the current row right to left
  const need = new Array(n + 1).fill(Infinity);
  for (let i = m - 1; i >= 0; i--) {
    for (let j = n - 1; j >= 0; j--) {
      let next = Math.min(need[j], need[j + 1]);
      if (i === m - 1 && j === n - 1) next = 1;
      need[j] = Math.max(1, next - vault[i][j]);
    }
  }
  return need[0];
}

